import{_ as t,o,c as a,ap as d}from"./chunks/framework.DL--BrMw.js";const h=JSON.parse('{"title":"API overview","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":null}'),s={name:"api/index.md"};function n(c,e,l,r,i,f){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="api-index" tabindex="-1">API overview <a class="header-anchor" href="#api-index" aria-label="Permalink to &quot;API overview {#api-index}&quot;">​</a></h1><p>The public interface, grouped by theme. Every exported name appears on exactly one of the pages below; the last one is a catch-all that lists anything not yet curated, so a newly exported symbol can never go undocumented.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">Covers</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./bases">Bases</a></td><td style="text-align:left;">basis types, metric, accessors, <code>init_*</code></td></tr><tr><td style="text-align:left;"><a href="./tensors">Tensors</a></td><td style="text-align:left;"><code>AbstractTens</code>, <code>Tens</code>, components, Kelvin-Mandel</td></tr><tr><td style="text-align:left;"><a href="./structured">Structured tensors</a></td><td style="text-align:left;"><code>TensISO</code> and the isotropic projectors</td></tr><tr><td style="text-align:left;"><a href="./walpole">Walpole and orthotropy</a></td><td style="text-align:left;"><code>TensTI</code>, <code>TensOrtho</code>, parametrizations</td></tr><tr><td style="text-align:left;"><a href="./cubic">Cubic symmetry</a></td><td style="text-align:left;"><code>TensCubic</code>, three constants and a cube frame</td></tr><tr><td style="text-align:left;"><a href="./projection">Projection</a></td><td style="text-align:left;"><code>project</code>, <code>best_sym_tens</code>, predicates</td></tr><tr><td style="text-align:left;"><a href="./special">Special tensors</a></td><td style="text-align:left;">Levi-Civita, rotations, unit vectors, random tensors</td></tr><tr><td style="text-align:left;"><a href="./coorsystems">Coordinate systems</a></td><td style="text-align:left;"><code>CoordinateSystem</code>, its exact geometry and the operators</td></tr><tr><td style="text-align:left;"><a href="./coorsystems_num">Numerical coordinate systems</a></td><td style="text-align:left;"><code>PointwiseGeometry</code></td></tr><tr><td style="text-align:left;"><a href="./submanifold">Submanifolds</a></td><td style="text-align:left;"><code>Submanifold</code> and its accessors</td></tr><tr><td style="text-align:left;"><a href="./symbolic">Symbolic helpers</a></td><td style="text-align:left;"><code>tsimplify</code>, <code>tsubs</code>, and the array algebra</td></tr><tr><td style="text-align:left;"><a href="./full_index">Full index</a></td><td style="text-align:left;">everything, alphabetically</td></tr></tbody></table><h2 id="api-renamed-0-11" tabindex="-1">Renamed in 0.11 <a class="header-anchor" href="#api-renamed-0-11" aria-label="Permalink to &quot;Renamed in 0.11 {#api-renamed-0-11}&quot;">​</a></h2><p>TensND 0.11 names each operation after what it does. The former names are removed, without a deprecation period, as are those 0.8 had deprecated (<code>KM</code>, <code>tens_TI</code>, <code>Walpole</code>, <code>coorsys_*_num</code>, …: the <a href="https://github.com/MicroPoroChemoMechanics/TensND.jl/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a> lists them with their successors). The moduli keep their symbols as exact aliases: <code>E_nu</code>, <code>k_mu</code>, <code>mu_nu</code> and <code>iso_stiffness_E_nu</code> are <a href="/TensND.jl/stable/api/structured#TensND.young_poisson"><code>young_poisson</code></a>, <a href="/TensND.jl/stable/api/structured#TensND.bulk_shear"><code>bulk_shear</code></a>, <a href="/TensND.jl/stable/api/structured#TensND.shear_poisson"><code>shear_poisson</code></a> and <a href="/TensND.jl/stable/api/structured#TensND.iso_stiffness_young_poisson"><code>iso_stiffness_young_poisson</code></a>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Name in 0.10</th><th style="text-align:left;">Name in 0.11</th></tr></thead><tbody><tr><td style="text-align:left;"><code>change_tens(t, ℬ[, var])</code>, <code>change_tens(t, var)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/tensors#TensND.express"><code>express</code></a><code>(t, ℬ[, var])</code>, <code>express(t, var)</code></td></tr><tr><td style="text-align:left;"><code>change_tens_canon(t)</code>, <code>components_canon(t)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/tensors#TensND.canonical"><code>canonical</code></a><code>(t)</code>, <a href="/TensND.jl/stable/api/tensors#TensND.canonical_components"><code>canonical_components</code></a><code>(t)</code></td></tr><tr><td style="text-align:left;"><code>mandel66_minor(A)</code>, <code>mandel33_minor(A)</code>, <code>mandel66(A)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/tensors#TensND.mandel"><code>mandel</code></a><code>(A; symmetrize = true)</code></td></tr><tr><td style="text-align:left;"><code>array_from_mandel66(M)</code>, <code>array_from_mandel33(M)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/tensors#TensND.from_mandel"><code>from_mandel</code></a><code>(M)</code> (its components: <code>get_array(from_mandel(M))</code>)</td></tr><tr><td style="text-align:left;"><code>tens_ti(C…, n)</code>, <code>ti_args(t)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/walpole#TensND.ti_from_constants"><code>ti_from_constants</code></a><code>(C…, n)</code>, <a href="/TensND.jl/stable/api/walpole#TensND.ti_constants"><code>ti_constants</code></a><code>(t)</code></td></tr><tr><td style="text-align:left;"><code>tens_ti_eng(…)</code>, <code>ti_args_eng(t)</code></td><td style="text-align:left;"><code>ti_from_constants(…; form = :engineering)</code>, <code>ti_constants(t; form = :engineering)</code></td></tr><tr><td style="text-align:left;"><code>tens_ti_hoenig(…)</code>, <code>ti_args_hoenig(t)</code></td><td style="text-align:left;"><code>ti_from_constants(…; form = :hoenig)</code>, <code>ti_constants(t; form = :hoenig)</code></td></tr><tr><td style="text-align:left;"><code>tens_cubic(C₁₁, C₁₂, C₄₄, frame)</code>, <code>arg_cubic(t)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/cubic#TensND.cubic_from_constants"><code>cubic_from_constants</code></a>, <a href="/TensND.jl/stable/api/cubic#TensND.cubic_constants"><code>cubic_constants</code></a></td></tr><tr><td style="text-align:left;"><code>get_ℓ(t)</code>, <code>get_ℓ8(t)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/walpole#TensND.walpole_coeffs"><code>walpole_coeffs</code></a><code>(t)</code>, <code>walpole_coeffs(t, Val(8))</code></td></tr><tr><td style="text-align:left;"><code>getcoords</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/coorsystems#TensND.get_coords"><code>get_coords</code></a></td></tr><tr><td style="text-align:left;"><code>rot2(θ)</code>, <code>rot3(θ, ϕ, ψ)</code>, <code>rot6(θ, ϕ, ψ)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/special#TensND.rotation_matrix"><code>rotation_matrix</code></a><code>(θ)</code>, <code>rotation_matrix(θ, ϕ, ψ)</code>, <a href="/TensND.jl/stable/api/special#TensND.rotation_tensor4"><code>rotation_tensor4</code></a><code>(θ, ϕ, ψ)</code></td></tr><tr><td style="text-align:left;"><code>proj_tens(:TI, A, n)</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/projection#TensND.project"><code>project</code></a><code>(A, :TI, n)</code></td></tr><tr><td style="text-align:left;"><code>ti_average_mandel66</code>, <code>iso_average_mandel66</code>, <code>ti_average_mat33</code></td><td style="text-align:left;"><a href="/TensND.jl/stable/api/projection#TensND.ti_average_mandel"><code>ti_average_mandel</code></a>, <a href="/TensND.jl/stable/api/projection#TensND.iso_average_mandel"><code>iso_average_mandel</code></a>, <a href="/TensND.jl/stable/api/projection#TensND.ti_average_matrix"><code>ti_average_matrix</code></a></td></tr></tbody></table><p><code>divergence</code> is Tensors.jl&#39;s function, extended to the coordinate systems, so that <code>using TensND, Tensors</code> leaves one <code>divergence</code>. The Hessian is <code>hess</code>, not <code>hessian</code>: SymPy, which TensND loads, exports a <code>hessian</code> of its own, and the same name would have made <code>using TensND, SymPyPythonCall</code> ambiguous.</p>',7)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
